// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *CustomerPostingGroup) InsertAll(records []*CustomerPostingGroup, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Code,
			r.Receivables_account,
			r.Service_charge_acc,
			r.Payment_disc_acc,
			r.Invoice_rounding_account,
			r.Additional_fee_account,
			r.Interest_account,
			r.Curr_appln_rounding_account,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CustomerPostingGroupTableName)
	columns := []string{"code", "receivables_account", "service_charge_acc", "payment_disc_acc", "invoice_rounding_account", "additional_fee_account", "interest_account", "curr_appln_rounding_account"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *CustomerPostingGroup) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CustomerPostingGroupTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			setClauses = append(setClauses, "code = ?")
			values = append(values, t.Code)
		}
		if t.hasFieldChanged("receivables_account") {
			setClauses = append(setClauses, "receivables_account = ?")
			values = append(values, t.Receivables_account)
		}
		if t.hasFieldChanged("service_charge_acc") {
			setClauses = append(setClauses, "service_charge_acc = ?")
			values = append(values, t.Service_charge_acc)
		}
		if t.hasFieldChanged("payment_disc_acc") {
			setClauses = append(setClauses, "payment_disc_acc = ?")
			values = append(values, t.Payment_disc_acc)
		}
		if t.hasFieldChanged("invoice_rounding_account") {
			setClauses = append(setClauses, "invoice_rounding_account = ?")
			values = append(values, t.Invoice_rounding_account)
		}
		if t.hasFieldChanged("additional_fee_account") {
			setClauses = append(setClauses, "additional_fee_account = ?")
			values = append(values, t.Additional_fee_account)
		}
		if t.hasFieldChanged("interest_account") {
			setClauses = append(setClauses, "interest_account = ?")
			values = append(values, t.Interest_account)
		}
		if t.hasFieldChanged("curr_appln_rounding_account") {
			setClauses = append(setClauses, "curr_appln_rounding_account = ?")
			values = append(values, t.Curr_appln_rounding_account)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "receivables_account = ?")
		values = append(values, t.Receivables_account)
		setClauses = append(setClauses, "service_charge_acc = ?")
		values = append(values, t.Service_charge_acc)
		setClauses = append(setClauses, "payment_disc_acc = ?")
		values = append(values, t.Payment_disc_acc)
		setClauses = append(setClauses, "invoice_rounding_account = ?")
		values = append(values, t.Invoice_rounding_account)
		setClauses = append(setClauses, "additional_fee_account = ?")
		values = append(values, t.Additional_fee_account)
		setClauses = append(setClauses, "interest_account = ?")
		values = append(values, t.Interest_account)
		setClauses = append(setClauses, "curr_appln_rounding_account = ?")
		values = append(values, t.Curr_appln_rounding_account)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Code)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND code = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Customer_Posting_Group: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *CustomerPostingGroup) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Code.Equal(old)
		}
	case "receivables_account":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Receivables_account.Equal(old)
		}
	case "service_charge_acc":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Service_charge_acc.Equal(old)
		}
	case "payment_disc_acc":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Payment_disc_acc.Equal(old)
		}
	case "invoice_rounding_account":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Invoice_rounding_account.Equal(old)
		}
	case "additional_fee_account":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Additional_fee_account.Equal(old)
		}
	case "interest_account":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Interest_account.Equal(old)
		}
	case "curr_appln_rounding_account":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Curr_appln_rounding_account.Equal(old)
		}
	}

	return false
}

